CREATE TABLE IF NOT EXISTS public._geo_snap_b7e21a4c (
  id uuid PRIMARY KEY,
  address_street text,
  address_city text,
  address_zip text,
  neighborhood text,
  lat numeric,
  lng numeric,
  reconstructed boolean NOT NULL DEFAULT true,
  snapped_at timestamptz NOT NULL DEFAULT now()
);

ON CONFLICT (id) DO NOTHING;

GRANT ALL ON public._geo_snap_b7e21a4c TO service_role;
ALTER TABLE public._geo_snap_b7e21a4c ENABLE ROW LEVEL SECURITY;
CREATE POLICY "service_role only" ON public._geo_snap_b7e21a4c TO service_role USING (true) WITH CHECK (true);